// Block (composition) — a value display that switches to an inline editing row.
// TextField/Button own editing controls and behavior; Stack owns arrangement and this Block owns edit state.
import { useEffect, useState, type Ref } from "react";
import { Button } from "../components/Button";
import { Stack } from "../layouts/Stack";
import { TextField } from "../components/TextField";
import "./InlineEdit.css";

export interface InlineEditProps {
  value: string;
  onSave?: (value: string) => void;
  label?: string;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function InlineEdit({
  value,
  onSave,
  label = "Edit value",
  className,
  ref,
}: InlineEditProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value);

  useEffect(() => {
    if (!editing) setDraft(value);
  }, [editing, value]);

  const cancel = () => {
    setDraft(value);
    setEditing(false);
  };

  const save = () => {
    onSave?.(draft);
    setEditing(false);
  };

  return (
    <div
      ref={ref}
      className={className ? `sd-inlineedit ${className}` : "sd-inlineedit"}
    >
      {/* usage: item-action — the whole Block edits one inline value, so its controls are small */}
      {editing ? (
        <Stack direction={{ small: "column", medium: "row" }} align={{ small: "stretch", medium: "end" }} gap="small" className="sd-inlineedit__editor">
          <TextField
            aria-label={label}
            value={draft}
            onChange={setDraft}
            autoFocus
            size="small"
            className="sd-inlineedit__field"
          />
          <Stack direction="row" gap="x-small" className="sd-inlineedit__actions">
            <Button size="small" onPress={save}>Save</Button>
            <Button size="small" variant="secondary" onPress={cancel}>Cancel</Button>
          </Stack>
        </Stack>
      ) : (
        /* usage: item-action — the value it edits is shown beside it */
        <Stack direction="row" align="center" justify="between" gap="small" className="sd-inlineedit__display">
          <span className="sd-inlineedit__value sd-type-body-medium">{value}</span>
          <Button size="small" variant="secondary" onPress={() => setEditing(true)}>
            Edit
          </Button>
        </Stack>
      )}
    </div>
  );
}
